72	
73	    /**
74	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
75	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
81	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
82	     */
83	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        List<OwnerDto> ownerDtos = owners.stream()
120	            .map(this::toOwnerDtoWithBulkWarning)
121	            .toList();
122	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        List<String> missingFields = new ArrayList<>();
139	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
140	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
141	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
142	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
143	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
144	        boolean hasStructuredAddress = !normalizedAddressLine1.isEmpty();
145	        String normalizedAddress = hasStructuredAddress
146	            ? composeAddress(normalizedAddressLine1, normalizedAddressLine2)
147	            : normalizedFlatAddress;
148	        requireNonBlank(missingFields, "address", normalizedAddress);
149	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
150	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
151	        if (!missingFields.isEmpty()) {
152	            throw new MissingRequiredFieldsException(missingFields);
153	        }
154	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
155	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
156	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
157	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
158	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
159	        requireDailyLimitNotReached(registrationDate);
160	        requireCityBelowCapacity(ownerFieldsDto.getCity());
161	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
162	        ownerFieldsDto.setTelephone(normalizedTelephone);
163	        if (ownerFieldsDto.getEmail() != null) {
164	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
165	        }
166	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        owner.setAddress(normalizedAddress);
170	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
171	        owner.setAddressLine2(hasStructuredAddress && !normalizedAddressLine2.isEmpty()
172	            ? normalizedAddressLine2 : null);
173	        owner.setRegistrationDate(registrationDate);
174	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
175	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
176	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
177	        requireUniqueIdentity(owner);
178	        requireNoHouseholdDuplicate(owner, sharesHousehold);
179	        markPossibleDuplicate(owner, sharesHousehold);
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
182	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
183	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
184	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
