361	    /**
362	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
363	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
364	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
365	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
366	     * {@code "+61412345678"}.
367	     *
368	     * @param telephone the raw telephone value from the request
369	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
370	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
371	     */
372	    private static String normalizeTelephone(String telephone) {
373	        String e164 = toE164(telephone);
374	        if (e164 == null) {
375	            throw new InvalidFieldValueException("telephone",
376	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
377	        }
378	        return e164;
379	    }
