381	    /**
382	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
383	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
384	     * owners' stored numbers when detecting duplicates.
385	     */
386	    private static String toE164(String telephone) {
387	        if (telephone == null) {
388	            return null;
389	        }
390	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
391	        String digits;
392	        if (cleaned.startsWith("+")) {
393	            digits = cleaned.substring(1);
394	        } else {
395	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
396	            digits = "61" + national;
397	        }
398	        if (!digits.matches("[0-9]{8,15}")) {
399	            return null;
400	        }
401	        if (!hasValidNationalLength(digits)) {
402	            return null;
403	        }
404	        return "+" + digits;
405	    }
406	
407	    /**
408	     * Checks the national-number length against the country code for the country codes that pin one.
409	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
410	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
411	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
412	     */
413	    private static boolean hasValidNationalLength(String digits) {
414	        if (digits.startsWith("61")) {
415	            return digits.length() - 2 == 9;
416	        }
417	        if (digits.startsWith("1")) {
418	            return digits.length() - 1 == 10;
419	        }
420	        return true;
421	    }
