715	    /**
716	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
717	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
718	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
719	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
720	     * value normalizes to the empty string, so the required-field check rejects an address that is
721	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
722	     *
723	     * @param address the raw address value from the request (may be {@code null})
724	     * @return the normalized address, or the empty string when blank after normalization
725	     */
726	    private static String normalizeAddress(String address) {
727	        if (address == null) {
728	            return "";
729	        }
730	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
731	        if (collapsed.isEmpty()) {
732	            return "";
733	        }
734	        String[] tokens = collapsed.split(" ");
735	        StringBuilder sb = new StringBuilder();
736	        for (String token : tokens) {
737	            String expanded = switch (token) {
738	                case "ST" -> "STREET";
739	                case "RD" -> "ROAD";
740	                case "AVE" -> "AVENUE";
741	                default -> token;
742	            };
743	            if (sb.length() > 0) {
744	                sb.append(' ');
745	            }
746	            sb.append(expanded);
747	        }
748	        return sb.toString();
749	    }
