56	@DependsOnDatabaseInitialization
57	@Repository
58	@Profile("jdbc")
59	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
60	
61	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
62	
63	    private SimpleJdbcInsert insertOwner;
64	
65	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
66	
67	        this.insertOwner = new SimpleJdbcInsert(dataSource)
68	            .withTableName("owners")
69	            .usingGeneratedKeyColumns("id");
70	
71	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
72	
73	    }
74	
75	
76	    /**
77	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
78	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
79	     * already loaded.
80	     */
81	    @Override
82	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
83	        Map<String, Object> params = new HashMap<>();
84	        params.put("lastName", lastName + "%");
85	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
86	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName",
87	            params,
88	            BeanPropertyRowMapper.newInstance(Owner.class)
89	        );
90	        loadOwnersPetsAndVisits(owners);
91	        return owners;
92	    }
93	
94	    @Override
95	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
96	        Map<String, Object> params = new HashMap<>();
97	        params.put("lastName", lastName + "%");
98	        params.put("size", pageable.getPageSize());
99	        params.put("offset", pageable.getOffset());
100	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
101	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
102	            params,
103	            BeanPropertyRowMapper.newInstance(Owner.class)
104	        );
105	        loadOwnersPetsAndVisits(owners);
106	        Long total = this.namedParameterJdbcTemplate.queryForObject(
107	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
108	            params,
109	            Long.class
110	        );
111	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
112	    }
113	
114	    /**
115	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
116	     * for the corresponding owner, if not already loaded.
117	     */
118	    @Override
119	    public Owner findById(int id) throws DataAccessException {
120	        Owner owner;
121	        try {
122	            Map<String, Object> params = new HashMap<>();
123	            params.put("id", id);
124	            owner = this.namedParameterJdbcTemplate.queryForObject(
125	                "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE id= :id",
126	                params,
127	                BeanPropertyRowMapper.newInstance(Owner.class)
128	            );
129	        } catch (EmptyResultDataAccessException ex) {
130	            throw new ObjectRetrievalFailureException(Owner.class, id);
