39	    /**
40	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
41	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
42	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
43	     * {@code null} when either the birth date or the registration date is absent.
44	     */
45	    @Named("toAgeBand")
46	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
47	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
48	            return null;
49	        }
50	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
51	        if (age < 18) {
52	            return OwnerDto.AgeBandEnum.MINOR;
53	        }
54	        if (age < 65) {
55	            return OwnerDto.AgeBandEnum.ADULT;
56	        }
57	        return OwnerDto.AgeBandEnum.SENIOR;
58	    }
