173	    /**
174	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
175	     * {@code null} when the postcode is absent, malformed, or in no known range.
176	     */
177	    private static String regionForPostcode(String postcode) {
178	        if (postcode == null || !postcode.matches("\\d{4}")) {
179	            return null;
180	        }
181	        int value = Integer.parseInt(postcode);
182	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
183	            int[] range = entry.getValue();
184	            if (value >= range[0] && value <= range[1]) {
185	                return entry.getKey();
186	            }
187	        }
188	        return null;
189	    }
