228	    default String toTelephoneDisplay(Owner owner) {
229	        if (owner == null) {
230	            return null;
231	        }
232	        String telephone = owner.getTelephone();
233	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
234	            return telephone;
235	        }
236	        String digits = telephone.substring(1);
237	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
238	        String countryCode = digits.substring(0, countryCodeLength);
239	        String national = digits.substring(countryCodeLength);
240	        StringBuilder sb = new StringBuilder("+").append(countryCode);
241	        for (int i = 0; i < national.length(); i++) {
242	            if (i % 3 == 0) {
243	                sb.append(' ');
244	            }
245	            sb.append(national.charAt(i));
246	        }
247	        return sb.toString();
248	    }
249	
250	    /**
251	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
252	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
253	     */
254	    @Named("toInitials")
255	    default String toInitials(Owner owner) {
256	        if (owner == null) {
257	            return null;
258	        }
259	        return initial(owner.getFirstName()) + initial(owner.getLastName());
260	    }
261	
262	    /**
263	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
264	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'NSW-1A2B3C4D-M26'}. Returns
265	     * {@code null} when either the customer code or the registration date is absent.
266	     */
267	    @Named("toMembershipNumber")
268	    default String toMembershipNumber(Owner owner) {
