340	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
341	     *
342	     * @param points the owner's membership points
343	     * @return the corresponding membership level (1-4)
344	     */
345	    static int membershipLevelFor(int points) {
346	        if (points <= 1) {
347	            return 1;
348	        }
349	        if (points <= 3) {
350	            return 2;
351	        }
352	        if (points <= 5) {
353	            return 3;
354	        }
355	        return 4;
356	    }
