364	    default Integer toCheckDigit(Owner owner) {
365	        if (owner == null || owner.getCustomerCode() == null) {
366	            return null;
367	        }
368	        int sum = 0;
369	        boolean dbl = true;
370	        String code = owner.getCustomerCode();
371	        for (int i = code.length() - 1; i >= 0; i--) {
372	            char c = code.charAt(i);
373	            if (c < '0' || c > '9') {
374	                continue;
375	            }
376	            int d = c - '0';
377	            if (dbl) {
378	                d *= 2;
379	                if (d > 9) {
380	                    d -= 9;
381	                }
382	            }
383	            sum += d;
384	            dbl = !dbl;
385	        }
386	        return (10 - (sum % 10)) % 10;
387	    }
388	
389	    private static String initial(String name) {
390	        if (name == null || name.isEmpty()) {
391	            return "";
392	        }
393	        return Character.toUpperCase(name.charAt(0)) + ".";
394	    }
395	
396	    Owner toOwner(OwnerDto ownerDto);
397	
398	    @Mapping(target = "id", ignore = true)
399	    @Mapping(target = "pets", ignore = true)
400	    Owner toOwner(OwnerFieldsDto ownerDto);
401	
402	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
403	
